export type GlyphName = keyof typeof GLYPHS;

export const GLYPH_NAMES = Object.keys(GLYPHS) as GlyphName[];

/** The bare SVG, for slots that already size it (the AppShell nav icon). */
export function Glyph({ name }: { name: GlyphName }): ReactNode {
  return (
    <svg
      viewBox="0 0 24 24"
      width="100%"
      height="100%"
      fill="none"
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: GLYPHS[name] }}
    />
  );
}

export interface ProductIconProps {
  name: GlyphName;
  size?: 16 | 20 | 24;
  /** accessible name; omit for decorative icons next to a visible word */
  label?: string;
  color?: string;
}

/** A product icon through the shared <Icon> wrapper. */
export function ProductIcon({ name, size = 20, label, color }: ProductIconProps) {
  return (
    <Icon size={size} label={label} color={color ?? "currentColor"}>
      <Glyph name={name} />
    </Icon>
  );
}
